      "claim": "Efficiency is a hollow metric if it destroys the very foundation of the consumer market.",
      "targets": []
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Aggregate demand is fundamentally tethered to human labor income.",
      "if_wrong": "If the economy can sustain itself via automated production without human wages, the threat of a collapse becomes a transition challenge rather than a terminal failure."
